"""Declarative base shared by every model."""

from datetime import datetime

from sqlalchemy import DateTime, MetaData, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

# A naming convention gives every constraint/index a predictable name
# (e.g. "ck_products_price_positive") instead of a random one generated by Postgres.
# Alembic needs stable names to drop or alter constraints in later migrations.
NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


def created_at_column() -> Mapped[datetime]:
    """Timestamp set by the database (not Python) so all rows share one clock."""
    return mapped_column(DateTime(timezone=True), server_default=func.now(), nullable=False)
